// Deep-linking URL parameter handler
(function($) {
    $(function() {
        var params = new URLSearchParams(window.location.search);
        var project = params.get('project');
        var amount = params.get('amount');
        var freq = params.get('freq');
        var type = params.get('type');
        var loc = params.get('location');

        if (freq === 'monthly') {
            $('#monthly').trigger('click');
        }

        if (project) {
            setTimeout(function() {
                var $proj = (freq === 'monthly') ? $('select.onem').first() : $('select.one').first();
                if ($proj.length) {
                    $proj.find('option').each(function() {
                        if ($(this).val().toLowerCase() === project.toLowerCase() || $(this).text().trim().toLowerCase() === project.toLowerCase()) {
                            $proj.val($(this).val()).trigger('change');
                            return false;
                        }
                    });
                }
            }, 100);
        }

        if (loc) {
            setTimeout(function() {
                var $loc = (freq === 'monthly') ? $('select.fourm').first() : $('select.four').first();
                if ($loc.length) {
                    $loc.find('option').each(function() {
                        if ($(this).val().toLowerCase() === loc.toLowerCase() || $(this).text().trim().toLowerCase() === loc.toLowerCase()) {
                            $loc.val($(this).val()).trigger('change');
                            return false;
                        }
                    });
                }
            }, 250);
        }

        if (type) {
            setTimeout(function() {
                var $type = (freq === 'monthly') ? $('select.fivem').first() : $('select.five').first();
                if ($type.length) {
                    $type.find('option').each(function() {
                        if ($(this).val().toLowerCase() === type.toLowerCase() || $(this).text().trim().toLowerCase() === type.toLowerCase()) {
                            $type.val($(this).val()).trigger('change');
                            return false;
                        }
                    });
                }
            }, 350);
        }

        if (amount) {
            setTimeout(function() {
                var $amt = (freq === 'monthly') ? $('input.sixm').first() : $('input.six').first();
                if ($amt.length) {
                    $amt.val(amount).trigger('keyup').trigger('change').trigger('input');
                }
            }, 450);
        }
    });
})(jQuery);
